"""Ekranlarda kalan aksansiz Turkce metinleri bulur.

JSX metin dugumleri ve arayuz nitelikleri (placeholder, baslik,
erisilebilirlik etiketi) taranir. Icinde Turkce'ye ozgu harf bulunan
metinler zaten duzeltilmis sayilir ve listelenmez.
"""
import io
import os
import re
import sys

KOK = sys.argv[1]
TURKCE = set('cgiosuCGIOSU')
AKSANLI = re.compile('[çğıöşüÇĞİÖŞÜ]')
HARF = re.compile('[A-Za-z]')
TEKNIK = re.compile(
    r'https?://|^[a-z]+[A-Z]|^#|^\d+$|px$|^rgba?\(|StyleSheet|require|'
    r'^[a-z_]+\.[a-z_]+$|^@|^[A-Z_]+$'
)

hedefler = []
for dizin, _, adlar in os.walk(os.path.join(KOK, 'src', 'app')):
    for ad in adlar:
        if ad.endswith('.tsx'):
            hedefler.append(os.path.join(dizin, ad))

for yol in sorted(hedefler):
    icerik = io.open(yol, encoding='utf-8').read()
    satirlar = icerik.split('\n')
    bulunan = []
    for no, satir in enumerate(satirlar, 1):
        kirpik = satir.strip()
        if kirpik.startswith('//') or kirpik.startswith('*'):
            continue
        adaylar = []
        for m in re.finditer(r'>\s*([^<>{}\n]{2,120}?)\s*<', satir):
            adaylar.append(m.group(1).strip())
        for m in re.finditer(
            r'(?:placeholder|accessibilityLabel|accessibilityHint|title|label|'
            r'accessibilityValue)\s*=\s*[{"\']([^"\'\n}]{2,120})',
            satir,
        ):
            adaylar.append(m.group(1).strip())
        for m in re.finditer(r"'([^'\n]{3,120})'|\"([^\"\n]{3,120})\"", satir):
            t = (m.group(1) or m.group(2)).strip()
            if ' ' in t:
                adaylar.append(t)
        for t in adaylar:
            if not t or not HARF.search(t) or TEKNIK.search(t):
                continue
            if AKSANLI.search(t):
                continue
            if not (set(t) & TURKCE):
                continue
            bulunan.append((no, t))
    if bulunan:
        print('==', yol.replace(KOK, '').replace(os.sep, '/').lstrip('/'))
        gorulen = set()
        for no, t in bulunan:
            if t in gorulen:
                continue
            gorulen.add(t)
            print('  %4d  %s' % (no, t))

