"""Metin duzeltmesinin koda tasip tasmadigini bulur.

Turkce'ye ozgu harfler yalnizca kullaniciya gorunen metinlerde,
yani dize sabitlerinin icinde olmali. Dize disinda bir yerde
gorunuyorsa bir tanimlayici yanlislikla degistirilmis demektir.
"""
import io
import os
import re
import sys

KOK = sys.argv[1]
AKSANLI = re.compile('[çğıöşüÇĞİÖŞÜ]')


def dize_disi(satir):
    """Satirin dize sabitleri disinda kalan bolumlerini dondurur."""
    parcalar = []
    tampon = []
    tirnak = None
    kacis = False
    for karakter in satir:
        if tirnak:
            if kacis:
                kacis = False
            elif karakter == '\\':
                kacis = True
            elif karakter == tirnak:
                tirnak = None
            continue
        if karakter in '\'"`':
            tirnak = karakter
            parcalar.append(''.join(tampon))
            tampon = []
            continue
        tampon.append(karakter)
    parcalar.append(''.join(tampon))
    return ' '.join(parcalar)


hedefler = []
for alt in ('src', 'lib', '__tests__'):
    for dizin, _, adlar in os.walk(os.path.join(KOK, alt)):
        for ad in adlar:
            if ad.endswith(('.ts', '.tsx')):
                hedefler.append(os.path.join(dizin, ad))

bulgu = 0
for yol in sorted(hedefler):
    satirlar = io.open(yol, encoding='utf-8').read().split('\n')
    blok = False
    for no, satir in enumerate(satirlar, 1):
        kirpik = satir.strip()
        if blok:
            if '*/' in satir:
                blok = False
            continue
        if kirpik.startswith('/*'):
            if '*/' not in satir:
                blok = True
            continue
        if kirpik.startswith('//') or kirpik.startswith('*'):
            continue
        kod = dize_disi(satir)
        kod = re.sub(r'//.*$', '', kod)
        if AKSANLI.search(kod):
            bulgu += 1
            print('%s:%d' % (yol.replace(KOK, '').replace(os.sep, '/').lstrip('/'), no))
            print('    ', satir.strip()[:150])

print()
print('kodda aksanli harf bulunan satir:', bulgu)

